// NEET UG Biology: Structural organisation in animals, animal tissues (NCERT Class 11, Chapter 7, 2023 rationalised). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `at-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}

// ---------------------------------------------------------------- Level 1
mc(1, 'basics', 'A group of similar cells that do a common job, along with the substance between them, is a', 'tissue', ['organ', 'organ system', 'organelle'], 'A tissue is a group of similar cells (with intercellular substance) that perform one or more functions.');
mc(1, 'basics', 'The four basic types of animal tissue are', 'epithelial, connective, muscular and neural', ['epithelial, areolar, muscular and neural', 'xylem, phloem, muscular and neural', 'epithelial, skeletal, blood and neural'], 'All animal tissues fall into these four groups.');
mc(1, 'epithelial', 'The tissue that covers body surfaces and lines hollow organs, ducts and cavities is', 'epithelial tissue', ['connective tissue', 'muscular tissue', 'neural tissue'], 'Epithelial tissue has a free surface facing a body fluid or the outside, with cells packed tightly and little intercellular matrix.');
mc(1, 'epithelial', 'The wall of the alveoli of the lungs is made of', 'simple squamous epithelium', ['simple columnar epithelium', 'stratified squamous epithelium', 'cuboidal epithelium'], 'A single thin layer of flat cells is best for diffusion of gases.');
mc(1, 'epithelial', 'A goblet cell of the alimentary canal is an example of a', 'unicellular exocrine gland', ['multicellular gland', 'endocrine gland', 'sensory cell'], 'Goblet cells are single glandular cells that secrete mucus.');
mc(1, 'connective', 'Tendons connect', 'skeletal muscle to bone', ['bone to bone', 'muscle to muscle', 'cartilage to skin'], 'Ligaments connect bone to bone.');
mc(1, 'connective', 'Adipose tissue is specialised to', 'store fat', ['conduct impulses', 'produce blood cells', 'carry oxygen'], 'Adipose tissue is a loose connective tissue beneath the skin where extra nutrients are stored as fat.');
mc(1, 'connective', 'The matrix of bone is hard because it is rich in', 'calcium salts and collagen fibres', ['elastic fibres only', 'water', 'plasma proteins'], 'Calcium salts and collagen give bone strength and weight-bearing ability.');
mc(1, 'connective', 'Cartilage cells are called', 'chondrocytes', ['osteocytes', 'fibroblasts', 'neurons'], 'Chondrocytes are in spaces (lacunae) of the solid, pliable matrix.');
mc(1, 'connective', 'Blood is a', 'fluid connective tissue', ['muscular tissue', 'epithelial tissue', 'neural tissue'], 'Blood has a fluid matrix (plasma) with RBCs, WBCs and platelets.');
mc(1, 'muscular', 'Muscles attached to bones, which we control by will, are', 'skeletal muscles', ['smooth muscles', 'cardiac muscles', 'visceral muscles'], 'Skeletal muscles are voluntary and striated.');
mc(1, 'muscular', 'Cardiac muscle is found', 'only in the heart', ['in the stomach wall', 'in the bones', 'in the brain'], 'Cardiac muscle is striated, branched and involuntary.');
mc(1, 'muscular', 'The muscles in the wall of the stomach and intestine are', 'smooth muscles', ['skeletal muscles', 'cardiac muscles', 'striated muscles'], 'Smooth (visceral) muscles lack striations and are involuntary.');
mc(1, 'neural', 'The unit of neural tissue that is excitable and conducts impulses is the', 'neuron', ['neuroglia', 'fibroblast', 'osteocyte'], 'Neurons receive and send signals. Neuroglia support and protect them.');

// ---------------------------------------------------------------- Level 2
mc(2, 'epithelial', 'Cuboidal epithelium is found in', 'the ducts of glands and tubular parts of nephrons', ['the alveoli of lungs', 'the lining of the stomach', 'the skin surface'], 'Cuboidal cells in these parts take part in secretion and absorption. Their walls are cube-like.');
mc(2, 'epithelial', 'The simple columnar epithelium lining the stomach and intestine functions in', 'secretion and absorption', ['protection against abrasion only', 'diffusion of gases', 'conduction of impulses'], 'Tall, pillar-like cells fit secretion and absorption. In the intestine they have microvilli as a brush border.');
mc(2, 'epithelial', 'Ciliated epithelium is found in', 'the bronchioles and fallopian tubes', ['the skin', 'the lining of blood vessels', 'the ducts of kidney only'], 'Cilia move particles or mucus in a specific direction, as in the respiratory tract.');
mc(2, 'epithelial', 'Compound epithelium is mainly for', 'protection against chemical and mechanical stresses', ['rapid diffusion', 'absorption of nutrients', 'gas exchange'], 'It has two or more layers (stratified) and its role in secretion and absorption is limited. It is found in the skin surface, buccal cavity and ducts of glands.');
mc(2, 'epithelial', 'Cells of the dry surface of the skin are', 'stratified squamous epithelium', ['simple squamous epithelium', 'simple cuboidal epithelium', 'ciliated epithelium'], 'Stratified layers protect the skin. Simple squamous is only one layer thick.');
mc(2, 'epithelial', 'Which of these glands is an exocrine gland?', 'Salivary gland', ['Thyroid', 'Pituitary', 'Adrenal'], 'Exocrine glands release secretions (mucus, saliva, earwax, oil, milk, enzymes) through ducts. Endocrine glands are ductless and release hormones into the fluid around them.', 'Endocrine glands have no ducts.');
mc(2, 'epithelial', 'Endocrine glands release their secretions', 'directly into the fluid bathing the gland', ['through ducts to body surface', 'into the alimentary canal', 'into the cytoplasm of neighbours only'], 'Ductless glands: hormones go into blood or tissue fluid.');
mc(2, 'epithelial', 'Which cell junction prevents leakage of substances across a tissue?', 'Tight junction', ['Gap junction', 'Adhering junction', 'Intercalated disc'], 'Tight junctions seal the gap between neighbouring cells. Adhering junctions cement cells. Gap junctions connect the cytoplasm.');
mc(2, 'epithelial', 'Gap junctions', 'connect the cytoplasm of adjoining cells for rapid transfer of ions and small molecules', ['seal the space between cells completely', 'cement cells together so they cannot move', 'secrete mucus'], 'They allow communication. Tight junctions seal, adhering junctions hold.');
mc(2, 'connective', 'Areolar tissue is an example of', 'loose connective tissue', ['dense regular connective tissue', 'cartilage', 'blood'], 'It is found beneath the skin. It has a loose network of fibres, fibroblasts and macrophages.');
mc(2, 'connective', 'Fibroblasts in connective tissue', 'secrete fibres and matrix', ['carry oxygen', 'conduct impulses', 'secrete hormones only'], 'Fibroblasts make collagen and other fibres. Macrophages engulf foreign matter.');
mc(2, 'connective', 'Ligaments and tendons are examples of', 'dense regular connective tissue', ['dense irregular connective tissue', 'loose connective tissue', 'adipose tissue'], 'Fibres lie in rows parallel to each other, giving strength in one direction.');
mc(2, 'connective', 'Dense irregular connective tissue is found in', 'the skin', ['tendons', 'ligaments', 'cartilage'], 'Fibroblasts and many fibres are oriented differently, as in the dermis of the skin.', 'Tendon and ligament are regular.');
mc(2, 'connective', 'Cartilage is found in', 'the tip of the nose, outer ear and between vertebrae', ['the shaft of the femur only', 'the stomach wall', 'the walls of blood vessels only'], 'Cartilage has a solid, pliable matrix that resists compression.');
mc(2, 'connective', 'Bone cells are lodged in spaces called', 'lacunae', ['alveoli', 'tubules', 'pits'], 'Osteocytes lie in lacunae within the hard matrix. Bone marrow in some bones produces blood cells.');
mc(2, 'connective', 'Which is not a component of blood?', 'Chondrocytes', ['Plasma', 'Platelets', 'White blood cells'], 'Chondrocytes are cartilage cells.');
mc(2, 'muscular', 'Why is skeletal muscle called striated?', 'It shows alternate light and dark bands', ['It is attached to bone', 'It is voluntary', 'It has a branched structure'], 'Striations are a visible banding pattern. Cardiac muscle is also striated.', 'Cardiac is also striated.');
mc(2, 'muscular', 'The cells of smooth muscle are', 'spindle-shaped, tapering at both ends, with no striations', ['long cylindrical with striations', 'branched and striated', 'multinucleate and attached to bone'], 'Smooth muscle cells are fusiform and have a single nucleus.');
mc(2, 'muscular', 'Intercalated discs are present in', 'cardiac muscle', ['skeletal muscle', 'smooth muscle', 'neural tissue'], 'Cell junctions fuse the plasma membranes of cardiac muscle cells. Communication junctions let them contract as a unit.');
mc(2, 'neural', 'Neuroglial cells', 'protect and support neurons and make up over half the volume of neural tissue', ['conduct nerve impulses', 'store fat', 'secrete hormones'], 'Neuroglia are non-conducting supporting cells.');
mc(2, 'neural', 'Neural tissue exerts the greatest control over the body by', 'detecting changes and sending responses', ['storing nutrients', 'protecting the skin', 'making blood'], 'Neurons are excitable cells. The brain, spinal cord and nerves are neural tissue.');
mc(2, 'epithelial', 'The microvilli (brush border) of intestinal cells increase', 'the surface area for absorption', ['the thickness of the epithelium', 'the secretion of mucus', 'the speed of peristalsis'], 'The brush border makes more surface for digested food to be absorbed.');
mc(2, 'epithelial', 'A feature common to all epithelial tissues is', 'cells packed tightly with little intercellular matrix', ['plenty of intercellular matrix', 'presence of blood vessels inside', 'only one layer in all types'], 'Epithelial cells are tightly joined. Compound epithelium has many layers.');
mc(2, 'connective', 'Connective tissue connects, supports and', 'binds various tissues and organs together', ['conducts impulses', 'contracts', 'secretes mucus only'], 'In nearly all connective tissues, cells are in a matrix (ground substance) with fibres, except blood where the matrix is fluid.');

// ---------------------------------------------------------------- Level 3
mc(3, 'epithelial', 'Which of the following is a correct match of epithelium and function?', 'Simple squamous: diffusion and filtration', ['Cuboidal: gas exchange', 'Ciliated: protection against abrasion', 'Compound: secretion only'], 'Thin flat cells suit diffusion and filtration. Compound epithelium is mainly protective; ciliated epithelium moves mucus.');
mc(3, 'epithelial', 'Which type lines the inner surface of the blood vessels?', 'Squamous epithelium', ['Columnar epithelium', 'Cuboidal epithelium', 'Stratified epithelium'], 'Smooth, thin cells reduce friction and allow exchange.');
mc(3, 'epithelial', 'Epithelium of the ducts of salivary glands and pancreatic ducts is', 'compound', ['simple squamous', 'ciliated columnar only', 'adipose'], 'Compound epithelium lines the buccal cavity, pharynx and inner ducts of salivary and pancreatic glands.');
mc(3, 'epithelial', 'Which junction type allows cells in the same epithelium to be cemented to neighbours?', 'Adhering junction', ['Tight junction', 'Gap junction', 'Plasmodesmata'], 'Adhering junctions perform cementing. Tight junctions stop leakage; gap junctions pass small molecules. Plasmodesmata occur in plants.', 'Plasmodesmata are plant structures.');
mc(3, 'epithelial', 'In multicellular exocrine glands, secretion reaches the surface through', 'ducts', ['blood', 'neurons', 'lymph only'], 'Duct-bearing glands include salivary glands. The ducts take the products to a surface or cavity.');
mc(3, 'epithelial', 'A gland that has both exocrine and endocrine parts is', 'pancreas', ['salivary gland', 'thyroid', 'sweat gland'], 'The pancreas secretes digestive enzymes through its duct and hormones into the blood.', 'Salivary and sweat glands are purely exocrine.');
mc(3, 'connective', 'The cell types seen in areolar tissue are', 'fibroblasts, macrophages and mast cells', ['osteocytes and chondrocytes', 'neurons and neuroglia', 'RBCs and platelets'], 'Areolar tissue is a loose network of fibres with these three cell types.');
mc(3, 'connective', 'Which of these tissues has a solid pliable matrix that resists compression?', 'Cartilage', ['Bone', 'Blood', 'Adipose tissue'], 'Cartilage matrix is firm but flexible. Bone matrix is rigid and hard.', 'Bone is hard, cartilage is pliable.');
mc(3, 'connective', 'Most cartilage in the adult is found in', 'the vertebral column between adjacent bones', ['the skull bones', 'the shaft of long bones', 'the muscle fibres'], 'Intervertebral discs are cartilage. Adult cartilage is also in the limbs and hands.');
mc(3, 'connective', 'Which of these connective tissues has a fluid matrix?', 'Blood', ['Bone', 'Cartilage', 'Adipose tissue'], 'Blood plasma is the fluid matrix.');
mc(3, 'connective', 'Dense regular tissue differs from dense irregular tissue in that', 'fibres lie in parallel rows between fibroblasts', ['it has no fibres', 'it has a fluid matrix', 'it stores fat'], 'Regular: parallel bundles. Irregular: bundles in random directions.');
mc(3, 'connective', 'The tissue that stores excess nutrients as fat is', 'loose connective tissue (adipose)', ['dense irregular tissue', 'cartilage', 'blood'], 'Adipose cells are specialised to store fat.');
mc(3, 'connective', 'A major function of bone marrow in some bones is', 'production of blood cells', ['storing fat only', 'making enzymes', 'conducting impulses'], 'Marrow in the cavity of some bones makes blood cells.');
mc(3, 'muscular', 'Which statement is true for skeletal muscle?', 'It is striated and voluntary', ['It is striated and involuntary', 'It is unstriated and voluntary', 'It is branched and involuntary'], 'Skeletal muscle is voluntary. Cardiac muscle is striated but involuntary.');
mc(3, 'muscular', 'Which muscle is both involuntary and striated?', 'Cardiac muscle', ['Skeletal muscle', 'Smooth muscle', 'Biceps'], 'Only cardiac muscle has both features.', 'Striated does not mean voluntary.');
mc(3, 'muscular', 'The muscle in the walls of blood vessels, stomach and intestine is also called', 'visceral muscle', ['striated muscle', 'cardiac muscle', 'voluntary muscle'], 'Smooth muscle is also called visceral or involuntary muscle.');
mc(3, 'muscular', 'The cell junctions in cardiac muscle', 'fuse the plasma membranes and let cells contract as a unit', ['seal spaces so no ions pass', 'are absent', 'bind bones'], 'Communication junctions at points of fusion allow rhythmic contraction of the heart.');
mc(3, 'neural', 'Which of the following is a function of neural tissue?', 'Control of body activities through impulses', ['Storage of fat', 'Production of blood cells', 'Absorption of food'], 'Neurons send impulses; the brain, spinal cord and nerves are neural tissue.');
mc(3, 'neural', 'Neuroglia form', 'more than half the volume of neural tissue', ['less than ten per cent of neural tissue', 'the conducting part of nerves', 'the muscles of the heart'], 'They protect and support neurons.', 'They do not conduct impulses.');
mc(3, 'connective', 'Which pair of cell and tissue is wrong?', 'Chondrocytes: bone', ['Osteocytes: bone', 'Fibroblasts: areolar tissue', 'Adipocytes: adipose tissue'], 'Chondrocytes are in cartilage. Osteocytes are in bone.');
mc(3, 'epithelial', 'Which feature is characteristic of simple columnar epithelium of the intestine?', 'Microvilli on the free surface', ['Several layers of cells', 'Flat cells', 'Cells with cilia'], 'The brush border is formed by microvilli.');
mc(3, 'epithelial', 'In a section of tissue the cells are cube-like, in a single layer, and line a duct. It is', 'simple cuboidal epithelium', ['simple squamous epithelium', 'compound epithelium', 'ciliated columnar epithelium'], 'Cube-shaped cells in one layer is the definition of simple cuboidal epithelium.');
mc(3, 'connective', 'The part of connective tissue between cells is the', 'matrix', ['lacuna', 'desmosome', 'lumen'], 'Matrix (ground substance) lies between cells and may be fluid, jelly-like, firm or solid.');
mc(3, 'connective', 'Collagen fibres in connective tissue provide', 'strength', ['conduction of impulses', 'secretion', 'contraction'], 'Collagen is strong. Elastic fibres give stretch and recoil.');
mc(3, 'muscular', 'The striations in skeletal muscle are due to', 'the regular arrangement of contractile proteins in bands', ['the nuclei in rows', 'the cell junctions', 'the connective tissue sheath'], 'The banded pattern is from repeated bands of contractile proteins.');
mc(3, 'muscular', 'Which of the following is NOT correct about smooth muscle?', 'It is attached to bones', ['It is involuntary', 'It is fusiform in shape', 'It is found in walls of internal organs'], 'Smooth muscle is not attached to bones. It is bundled with a connective tissue sheath in visceral organs.');
mc(3, 'connective', 'A ligament is correctly described as', 'dense regular connective tissue joining bone to bone', ['dense regular connective tissue joining muscle to bone', 'loose connective tissue joining muscle to muscle', 'elastic cartilage of the ear'], 'Tendon: muscle to bone. Ligament: bone to bone.', 'Tendon/ligament reversal.');

// ---------------------------------------------------------------- Assertion and Reason
asr(2, 'epithelial', 'Simple squamous epithelium lines the alveoli of the lungs.', 'It is a single layer of thin, flat cells, which favours diffusion.', 0, 'Both are true. A single thin layer shortens the diffusion distance, so R explains A.');
asr(3, 'epithelial', 'Endocrine glands do not have ducts.', 'Endocrine glands release their secretions directly into the fluid bathing the gland.', 0, 'Both are true. With no ducts, hormones diffuse into the fluid around the gland and enter the blood, so R explains A.');
asr(3, 'connective', 'Tendons are strong and inextensible.', 'Tendons are made of dense regular connective tissue with parallel collagen fibres.', 0, 'Both are true. The tight parallel collagen bundles give the strength, so R explains A.');
asr(4, 'muscular', 'Cardiac muscle fibres contract as a unit.', 'Cardiac muscle cells are joined by communication junctions at points of fusion.', 0, 'Both are true. The junctions pass the signal between cells, so R explains A.');
asr(4, 'muscular', 'Skeletal muscle is striated.', 'Smooth muscle is also striated.', 2, 'A is true. R is false: smooth muscle is unstriated. The striated types are skeletal and cardiac.');
asr(3, 'connective', 'Blood is a connective tissue.', 'Blood has a fluid matrix, plasma, and no cells.', 2, 'A is true. R is false: blood has plasma and also RBCs, WBCs and platelets.');
asr(4, 'epithelial', 'Tight junctions prevent leakage across epithelium.', 'Gap junctions are the junctions that cement neighbouring cells together.', 2, 'A is true: tight junctions seal the space between cells. R is false: adhering junctions do the cementing; gap junctions connect the cytoplasm of adjoining cells.');
asr(5, 'neural', 'Neuroglia are the supporting and protecting cells of neural tissue.', 'Neuroglia make up more than half the volume of neural tissue.', 1, 'Both are true. The volume is a fact about neuroglia, but it does not explain their function of support and protection.');
asr(4, 'connective', 'Cartilage can resist compression.', 'Cartilage has a solid, pliable matrix.', 0, 'Both are true. The firm yet flexible matrix lets it resist pressure, so R explains A.');
asr(5, 'connective', 'Dense irregular connective tissue is found in the skin.', 'In it, the fibres are oriented in many directions, so it resists pull from many directions.', 0, 'Both are true. Random orientation allows strength in many directions.');

// ---------------------------------------------------------------- Statements
stm(2, 'epithelial', 'Stratified squamous epithelium lines the buccal cavity.', 'Stratified squamous epithelium is made of only one layer of cells.', 2, 'I is true. II is false: stratified means many layers.');
stm(3, 'epithelial', 'Tight junctions connect the cytoplasm of adjoining cells.', 'Gap junctions let ions and small molecules pass between cells.', 3, 'I is false: tight junctions seal the space between cells. II is true: gap junctions connect the cytoplasm of adjoining cells.');
stm(3, 'connective', 'Bone cells are called osteocytes.', 'Osteocytes lie in the lacunae of the hard matrix.', 0, 'Both are true.');
stm(3, 'connective', 'Ligaments join muscle to bone.', 'Tendons join bone to bone.', 1, 'Both are wrong: ligaments join bone to bone; tendons join muscle to bone.');
stm(4, 'muscular', 'Cardiac muscle is involuntary and striated.', 'Skeletal muscle is involuntary and unstriated.', 2, 'I is true. II is false: skeletal muscle is voluntary and striated.');
stm(4, 'muscular', 'Smooth muscle is found in the wall of the heart.', 'Smooth muscle cells taper at both ends.', 3, 'I is false: the heart wall has cardiac muscle. II is true: smooth muscle cells are fusiform.');
stm(3, 'epithelial', 'Goblet cells are unicellular glands.', 'Salivary glands are multicellular glands.', 0, 'Both are true.');
stm(4, 'connective', 'Adipose tissue is a loose connective tissue.', 'Adipose cells are specialised to store fat.', 0, 'Both are true.');
stm(5, 'neural', 'Neuroglia make up less than half of the volume of neural tissue.', 'Neurons are excitable cells.', 3, 'I is false: they make up more than half. II is true.');
stm(5, 'epithelial', 'Ciliated epithelium moves particles in a specific direction.', 'It is found in the lining of the stomach.', 2, 'I is true. II is false: it is in bronchioles and fallopian tubes. The stomach has simple columnar epithelium.');
stm(5, 'connective', 'In most connective tissue the cells are present in a matrix.', 'Blood is a connective tissue in which the matrix is solid.', 2, 'I is true. II is false: the matrix of blood is fluid plasma.');

// ---------------------------------------------------------------- Match the following
match(2, 'epithelial', 'atm1', 'Epithelium and place', ['A. Simple squamous', 'B. Simple cuboidal', 'C. Simple columnar', 'D. Ciliated'], ['p. Bronchioles', 'q. Walls of alveoli', 'r. Ducts of glands', 's. Lining of stomach'], 'A-q, B-r, C-s, D-p', ['A-r, B-q, C-s, D-p', 'A-q, B-r, C-p, D-s', 'A-s, B-r, C-q, D-p'], 'Squamous: alveoli. Cuboidal: ducts of glands and tubules. Columnar: stomach and intestine. Ciliated: bronchioles and fallopian tubes.');
match(3, 'junctions', 'atm2', 'Junction and function', ['A. Tight junction', 'B. Adhering junction', 'C. Gap junction', 'D. Goblet cell'], ['p. Cements neighbouring cells', 'q. Connects the cytoplasm of adjoining cells', 'r. Prevents leakage across the tissue', 's. Unicellular gland'], 'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-q, C-p, D-s', 'A-s, B-p, C-q, D-r'], 'Tight: no leakage. Adhering: cementing. Gap: cytoplasmic connection. Goblet: unicellular gland.');
match(3, 'connective', 'atm3', 'Tissue and example', ['A. Dense regular', 'B. Dense irregular', 'C. Cartilage', 'D. Loose'], ['p. Skin dermis', 'q. Tendon', 'r. Ear pinna', 's. Areolar tissue'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Tendon is dense regular, dermis is dense irregular, ear pinna is cartilage and areolar tissue is loose.');
match(4, 'muscular', 'atm4', 'Muscle and feature', ['A. Skeletal', 'B. Smooth', 'C. Cardiac', 'D. Neuroglia'], ['p. Intercalated discs', 'q. Fusiform and unstriated', 'r. Striated and voluntary', 's. Supports neurons'], 'A-r, B-q, C-p, D-s', ['A-q, B-r, C-p, D-s', 'A-r, B-q, C-s, D-p', 'A-p, B-q, C-r, D-s'], 'Skeletal is striated and voluntary. Smooth is fusiform and unstriated. Cardiac has intercalated discs. Neuroglia support neurons.');

// ---------------------------------------------------------------- Passages
pass('atp1', 'Passage: a slide under the microscope', 'A student studies a slide of a tissue. The cells are tall and pillar-like, in a single layer, with oval nuclei at the base. Their free surface has fine finger-like projections. Among them are a few single cells that secrete a slippery fluid. The tissue lines a part of the digestive tract.');
pq('atp1', 3, 'epithelial', 'The tissue is', 'simple columnar epithelium', ['simple squamous epithelium', 'stratified squamous epithelium', 'dense regular connective tissue'], 'Tall, pillar-like cells in a single layer: simple columnar.');
pq('atp1', 3, 'epithelial', 'The finger-like projections on the free surface are', 'microvilli that increase the surface for absorption', ['cilia that move food', 'dendrites', 'collagen fibres'], 'They form the brush border of the intestine.', 'Cilia are not in the intestine.');
pq('atp1', 4, 'epithelial', 'The single secretory cells among the lining cells are', 'goblet cells, unicellular exocrine glands', ['mast cells', 'multicellular endocrine glands', 'fibroblasts'], 'Goblet cells secrete mucus and are the example of unicellular glands in NCERT.');
pass('atp2', 'Passage: a tissue from the leg', 'A tissue slide shows parallel bundles of tough fibres with rows of flat cells between them. The tissue joins a muscle at one end to a bone at the other. A second slide shows cells inside tiny spaces in a firm, rubbery matrix. It is taken from the disc between two vertebrae.');
pq('atp2', 3, 'connective', 'The first tissue is', 'dense regular connective tissue (a tendon)', ['dense irregular tissue (skin)', 'cartilage', 'adipose tissue'], 'Parallel fibres and rows of fibroblasts, linking muscle to bone: a tendon.');
pq('atp2', 3, 'connective', 'The second tissue is', 'cartilage, with chondrocytes in lacunae', ['bone with osteocytes', 'blood with plasma', 'areolar tissue with mast cells'], 'A firm but pliable matrix between vertebrae is cartilage.', 'Bone is hard; this is rubbery.');
pq('atp2', 4, 'connective', 'A band of the first tissue that joined one bone to another would be called', 'a ligament', ['a tendon', 'a cartilage', 'a marrow'], 'It has the same dense regular structure; the name depends on what it joins.');

// ---------------------------------------------------------------- Level 4 and 5
mc(4, 'epithelial', 'In which of the following is the simple epithelium NOT matched with its function?', 'Cuboidal: protection from abrasion', ['Squamous: filtration', 'Columnar: absorption', 'Ciliated: movement of mucus'], 'Cuboidal epithelium is for secretion and absorption. Protection is for compound epithelium.');
mc(4, 'epithelial', 'Which of the following is the best example of a multicellular exocrine gland?', 'Salivary gland', ['Goblet cell', 'Thyroid', 'Adrenal'], 'Goblet cell is unicellular. Thyroid and adrenal are endocrine.');
mc(4, 'epithelial', 'The cell junctions that help cells of an epithelium act as a barrier to leakage are', 'tight junctions', ['adhering junctions', 'gap junctions', 'intercalated discs'], 'Tight junctions block fluid movement between cells.', 'Adhering junctions hold; they do not seal.');
mc(4, 'connective', 'How many of the following are connective tissues: blood, bone, tendon, adipose tissue, smooth muscle?', 'Four', ['Three', 'Five', 'Two'], 'Blood, bone, tendon and adipose tissue are connective. Smooth muscle is muscular tissue.', 'Count carefully: smooth muscle is not connective.');
mc(4, 'connective', 'Which of these tissues has cells lying in a matrix rich in calcium salts?', 'Bone', ['Cartilage', 'Blood', 'Areolar tissue'], 'Calcium salts harden bone.');
mc(4, 'connective', 'A student confuses bone and cartilage. Which feature is found only in bone?', 'Hard matrix with calcium salts', ['Cells in lacunae', 'Collagen fibres', 'Presence of matrix'], 'Both bone and cartilage have cells in lacunae with collagen in the matrix. Calcium-rich hardness is for bone.');
mc(4, 'connective', 'Which of the following is NOT a function of connective tissue?', 'Rapid conduction of nerve impulses', ['Support of organs', 'Storage of fat', 'Transport of substances'], 'Conduction of impulses is the task of neural tissue.');
mc(4, 'muscular', 'The intercalated discs help cardiac muscle in', 'contracting as a unit', ['voluntary control', 'attachment to bones', 'storing fat'], 'The communication junctions let signals pass.');
mc(4, 'muscular', 'Which muscle shows both unbranched fibres and attachment to bones?', 'Skeletal muscle', ['Cardiac muscle', 'Smooth muscle', 'Visceral muscle'], 'Cardiac fibres are branched; smooth muscle is not attached to bones.');
mc(4, 'muscular', 'Biceps of the arm are made of', 'striated voluntary muscle', ['smooth muscle', 'cardiac muscle', 'dense connective tissue only'], 'Biceps is a skeletal muscle.');
mc(4, 'neural', 'The two cell types of neural tissue are', 'neurons and neuroglia', ['neurons and fibroblasts', 'neuroglia and macrophages', 'neurons and osteocytes'], 'Neurons are excitable. Neuroglia support and protect.');
mc(4, 'mixed', 'A tissue that is made of cells that contract and are attached to bones, and is covered by a connective tissue sheath, also has tendons at its ends. Tendons are made of', 'dense regular connective tissue', ['skeletal muscle', 'cartilage', 'dense irregular connective tissue'], 'Muscle is attached to bones by tendons, which are dense regular connective tissue.');
mc(4, 'mixed', 'In the digestive tract wall the lining epithelium, the muscle and the nerve cells belong to', 'epithelial, smooth muscle and neural tissue respectively', ['connective, cardiac and neural', 'epithelial, skeletal and connective', 'neural, smooth and epithelial'], 'A single organ uses several tissue types.');
mc(4, 'mixed', 'Which of the following does the tissue lining kidney tubules most likely provide?', 'Secretion and absorption by cuboidal cells', ['Contraction', 'Impulse conduction', 'Fat storage'], 'Cuboidal epithelium forms the tubular parts of nephrons.');
mc(4, 'epithelial', 'Which feature of ciliated epithelium suits it to the respiratory tract?', 'Cilia move mucus in one direction', ['Cells are flat for diffusion', 'It is thick and layered', 'It stores mucus as a gland'], 'This clears particles in the bronchioles.');
mc(4, 'epithelial', 'Which type of epithelium would you expect lining a duct that is exposed to wear and mechanical stress?', 'Stratified (compound) epithelium', ['Simple squamous', 'Simple cuboidal', 'Goblet cells only'], 'Multiple layers protect from abrasion.');
mc(5, 'connective', 'Choose the group in which all are examples of specialised connective tissue.', 'Cartilage, bone and blood', ['Tendon, ligament and skin dermis', 'Areolar tissue, adipose tissue and bone', 'Cartilage, tendon and blood'], 'Specialised: cartilage, bone, blood. Dense regular (tendon, ligament) and dense irregular (skin) tissues are dense connective tissue; areolar and adipose are loose.', 'Adipose and areolar are loose, not specialised.');
mc(5, 'epithelial', 'Which of these cell junction sets correctly pairs a function with its name?', 'Tight: stop leakage; adhering: cementing; gap: cytoplasmic communication', ['Tight: cementing; adhering: leakage; gap: sealing', 'Tight: communication; adhering: leakage; gap: cementing', 'Tight: sealing; adhering: communication; gap: cementing'], 'NCERT: tight junctions prevent leakage, adhering junctions cement neighbouring cells, gap junctions facilitate communication.');
mc(5, 'muscular', 'Which of these features is shared by skeletal and cardiac muscle but not smooth muscle?', 'Striations', ['Voluntary control', 'Branching', 'Tapering ends'], 'Both skeletal and cardiac are striated. Only skeletal is voluntary and only cardiac is branched.', 'Do not choose voluntary: cardiac is involuntary.');
mc(5, 'mixed', 'How many of these are living cells (not dead) in their tissue: chondrocyte, osteocyte, goblet cell, neuron, RBC of human, macrophage?', 'Six', ['Five', 'Four', 'Three'], 'All six are living cells. A human RBC lacks a nucleus but is alive.', 'Anucleate is not the same as dead.');
mc(5, 'neural', 'The cell type that forms the larger fraction of neural tissue by volume is', 'neuroglia', ['neurons', 'fibroblasts', 'macrophages'], 'Neuroglia make up more than half the volume. Neurons are the conducting cells.', 'Neurons are the famous cells but not the larger part.');

// ---------------------------------------------------------------- Expansion (added 2026-11-22)
// ---- Level 2
mc(2, 'basics', 'How many basic types of tissue are recognised in animals?', 'Four', ['Three', 'Five', 'Six'], 'Epithelial, connective, muscular and neural: four.');
mc(2, 'epithelial', 'Which tissue has cells packed tightly with very little intercellular matrix?', 'Epithelial tissue', ['Areolar tissue', 'Bone', 'Blood'], 'Epithelial cells are compactly packed with only a little intercellular material. Connective tissues have cells spread in a matrix.');
mc(2, 'epithelial', 'Which of these is NOT released by an exocrine gland through a duct?', 'A hormone', ['Mucus', 'Saliva', 'Earwax'], 'Hormones come from ductless endocrine glands and pass into the fluid around them. Mucus, saliva and earwax leave through ducts.');
mc(2, 'epithelial', 'Thin, flat cells in a single layer are best suited for', 'diffusion and filtration', ['protection against abrasion', 'secretion of enzymes', 'moving mucus'], 'A very thin layer keeps the diffusion distance short, so simple squamous epithelium is used where gases or fluids pass.');
mc(2, 'epithelial', 'The inner lining of the buccal cavity and pharynx is made of', 'compound (stratified) epithelium', ['simple squamous epithelium', 'simple cuboidal epithelium', 'ciliated epithelium'], 'These surfaces face wear and tear, so a many-layered covering is used.');
mc(2, 'connective', 'Adipose tissue is located mainly', 'beneath the skin', ['in the brain', 'inside blood vessels', 'in the lining of alveoli'], 'Its cells are specialised to store fat, and the layer lies below the skin.');
mc(2, 'connective', 'The matrix of blood is called', 'plasma', ['lymph', 'collagen', 'serum'], 'Plasma is the fluid matrix in which RBCs, WBCs and platelets are suspended.', 'Serum is plasma without clotting factors; it is not the matrix.');
mc(2, 'connective', 'The collagen fibres of dense regular connective tissue lie', 'in parallel rows between rows of fibroblasts', ['in random directions', 'only around blood cells', 'in a fluid matrix'], 'Tendons and ligaments have fibres packed in orderly parallel bundles. In dense irregular tissue the fibres run in different directions.');
mc(2, 'connective', 'The outer ear (pinna) is supported by', 'cartilage', ['bone', 'adipose tissue', 'smooth muscle'], 'Cartilage is pliable yet resists compression, so it keeps the pinna in shape and lets it bend.');
mc(2, 'muscular', 'Which tissue forms most of the wall of the heart?', 'Cardiac muscle', ['Skeletal muscle', 'Smooth muscle', 'Neural tissue'], 'Cardiac muscle is found only in the heart.');
mc(2, 'neural', 'The brain and spinal cord are made mainly of', 'neural tissue', ['muscular tissue', 'epithelial tissue', 'adipose tissue'], 'Neural tissue controls and coordinates the body through the brain, spinal cord and nerves.');
mc(2, 'connective', 'A cell that lies in a lacuna of cartilage is a', 'chondrocyte', ['fibroblast', 'osteocyte', 'macrophage'], 'Chondrocytes sit in small cavities in the cartilage matrix that they themselves secrete.', 'Osteocytes are in bone.');

// ---- Level 3
mc(3, 'connective', 'Which pair of cells is found in areolar tissue along with fibroblasts?', 'Macrophages and mast cells', ['Chondrocytes and osteocytes', 'Neurons and neuroglia', 'Goblet cells and RBCs'], 'Areolar tissue has fibroblasts, macrophages and mast cells in a loose network of collagen and elastic fibres.');
mc(3, 'connective', 'Which two kinds of fibre are present in areolar tissue?', 'Collagen and elastic fibres', ['Collagen and myofibrils', 'Elastic fibres and neurofibrils', 'Actin and myosin'], 'Collagen gives strength; elastic fibres give stretch and recoil. Actin and myosin are muscle proteins.');
mc(3, 'connective', 'Which of these is a loose connective tissue?', 'Areolar tissue', ['Tendon', 'Ligament', 'Dermis of the skin'], 'NCERT groups areolar tissue and adipose tissue as loose connective tissue. Tendons and ligaments are dense regular, and the dermis is dense irregular.', 'Adipose tissue is also loose, but it is not among the options.');
mc(3, 'connective', 'Which of the following is a dense connective tissue with fibres arranged in different directions?', 'The dermis of the skin', ['A tendon', 'A ligament', 'Adipose tissue'], 'Dense irregular tissue has many collagen fibres oriented in different directions and is found in the skin. Tendons and ligaments have parallel fibres.');
mc(3, 'connective', 'Bone differs from cartilage because its matrix is', 'hard and non-pliable, rich in calcium salts', ['fluid', 'free of collagen', 'free of cells'], 'Both have cells in cavities and collagen in the matrix. Calcium salts make bone hard.');
mc(3, 'connective', 'Which connective tissue helps in blood cell formation in some bones?', 'Bone marrow within the bone', ['Dense regular tissue', 'Adipose tissue under the skin', 'Cartilage of the ear'], 'NCERT: bone marrow in some bones is the site of blood cell production.');
mc(3, 'muscular', 'Which statement about smooth muscle is correct?', 'Its fibres are bundled in a connective tissue sheath and are involuntary', ['It has dark and light bands', 'It is attached to bones by tendons', 'Its fibres are branched with intercalated discs'], 'Smooth muscle is unstriated and in the walls of internal organs; control is not voluntary.');
mc(3, 'muscular', 'Which muscle type has fibres that are branched?', 'Cardiac muscle', ['Skeletal muscle', 'Smooth muscle', 'None of them'], 'Cardiac fibres branch and join at intercalated discs.');
mc(3, 'muscular', 'The wave of contraction spreads rapidly through cardiac muscle because', 'communication junctions at the fusion points allow signals to pass', ['all its fibres are voluntary', 'it is surrounded by bone', 'it has no plasma membrane'], 'Plasma membranes of adjacent cells are fused at intercalated discs, and communication junctions let the contraction wave spread.');
mc(3, 'neural', 'What fraction of neural tissue volume do neuroglia form?', 'More than half', ['Less than a tenth', 'Exactly one fourth', 'None; they are outside neural tissue'], 'NCERT: neuroglial cells make up more than one-half the volume of neural tissue.', 'Neurons get the fame, but neuroglia are the larger share.');
mc(3, 'epithelial', 'Which feature is present on the free surface of many simple cuboidal or columnar cells that absorb nutrients?', 'Microvilli', ['Myofibrils', 'Lacunae', 'Intercalated discs'], 'Microvilli enlarge the surface for absorption, forming a brush border.');
mc(3, 'epithelial', 'Cilia on the lining of the respiratory passage mainly help to', 'move mucus with trapped particles in one direction', ['absorb nutrients', 'secrete enzymes', 'store fat'], 'Their coordinated beating moves mucus along the passage.');
mc(3, 'epithelial', 'In simple columnar epithelium the nuclei usually lie', 'near the base of the cells', ['near the free surface', 'outside the cells', 'in the middle of the matrix'], 'The cells are tall and slender with oval nuclei towards the base.');
mc(3, 'epithelial', 'The cell junctions that connect the cytoplasm of adjoining cells for rapid transfer of ions and small molecules are', 'gap junctions', ['tight junctions', 'adhering junctions', 'desmosomes only as a seal'], 'Gap junctions are channels linking neighbouring cytoplasm.');
mc(3, 'epithelial', 'The tissue that lines the ducts of salivary glands is', 'compound epithelium', ['simple squamous epithelium', 'neural tissue', 'adipose tissue'], 'NCERT lists the inner lining of ducts of salivary glands and pancreatic ducts as compound epithelium.');
mc(3, 'glands', 'The pancreas is an example of a gland that is', 'both exocrine and endocrine', ['only exocrine', 'only endocrine', 'unicellular'], 'It releases digestive enzymes through a duct and hormones into the blood.', 'People call it a hormone gland only.');
mc(3, 'glands', 'A gland that releases secretions into the fluid around it without ducts is', 'an endocrine gland', ['an exocrine gland', 'a goblet cell', 'a sweat pore'], 'Endocrine glands are ductless and secrete hormones.');
mc(3, 'basics', 'Which of these tissues is NOT present in the wall of a blood vessel?', 'Bone', ['Simple squamous epithelium', 'Smooth muscle', 'Connective tissue'], 'Blood vessels have a squamous lining, smooth muscle and connective tissue. Bone is never part of the wall.');
mc(3, 'basics', 'Cells that are living but lack a nucleus when mature are found in which tissue?', 'Blood', ['Bone', 'Cartilage', 'Neural tissue'], 'Mature human RBCs have no nucleus, though they are alive.');
mc(3, 'connective', 'Which of these is NOT a place where cartilage is found in adults?', 'The matrix of the skull bones as a hard calcified plate', ['The tip of the nose', 'The outer ear', 'Between adjacent vertebrae'], 'NCERT lists the tip of nose, outer ear joints and the spaces between vertebrae. Skull bones are bone.');
mc(3, 'muscular', 'Which of these muscles is NOT under voluntary control?', 'Muscle of the stomach wall', ['Biceps', 'Muscles of the leg', 'Muscles of the fingers'], 'Smooth muscle of internal organs is involuntary.');
mc(3, 'epithelial', 'Tall, pillar-like cells that secrete and absorb are typical of', 'simple columnar epithelium', ['simple squamous epithelium', 'stratified epithelium', 'dense connective tissue'], 'Tall cells have room for organelles that serve secretion and absorption.');
mc(3, 'connective', 'Fibroblasts are cells that mainly', 'secrete fibres of the connective tissue matrix', ['conduct nerve impulses', 'store fat only', 'carry oxygen'], 'They make collagen and other fibres in loose and dense connective tissue.');

asr(3, 'epithelial', 'Cuboidal epithelium is common in the tubular parts of nephrons.', 'Cuboidal cells are specialised for secretion and absorption.', 0, 'The role of cuboidal epithelium in secretion and absorption explains its presence where the kidney tubule reabsorbs and secretes.');
asr(3, 'connective', 'Tendons can withstand strong pulling forces.', 'Dense regular tissue has collagen fibres packed in parallel bundles.', 0, 'Parallel, tightly packed collagen bundles give great tensile strength, so R explains A.');
asr(4, 'muscular', 'Smooth muscle is also called involuntary muscle.', 'Smooth muscle fibres are striated.', 2, 'A is true: its action is not under our will. R is false: smooth muscle has no striations.');
asr(4, 'connective', 'Cartilage can bear compression better than areolar tissue.', 'Cartilage has a solid, pliable matrix whereas areolar tissue is a loose network of fibres.', 0, 'The solid pliable matrix resists compression; the loose mesh of areolar tissue does not.');
asr(4, 'neural', 'Neuroglia conduct nerve impulses just as neurons do.', 'Neuroglia protect and support neurons.', 3, 'A is false: neurons are the excitable cells that conduct impulses. R is true.');
asr(4, 'epithelial', 'Gap junctions are useful in cardiac muscle and in epithelia.', 'Gap junctions seal the space between cells so that nothing can leak.', 2, 'A is true: gap junctions let ions and small molecules pass between cells. R is false: sealing is done by tight junctions.');
asr(5, 'connective', 'Tendon is a dense regular connective tissue.', 'Tendons connect one bone to another.', 2, 'A is true. R is false: tendons join muscle to bone; ligaments join bone to bone.');
asr(5, 'epithelial', 'A goblet cell is a gland even though it is a single cell.', 'A goblet cell secretes mucus onto the free surface.', 0, 'A single secretory cell that discharges mucus qualifies as a unicellular exocrine gland, so R explains A.');
asr(5, 'blood', 'Blood is classed as a connective tissue.', 'Blood contains cells suspended in a fluid matrix.', 0, 'Connective tissue means cells set in a matrix. Blood has plasma as matrix, so R explains A.');
asr(5, 'muscular', 'All three types of muscle are contractile.', 'Cardiac muscle is voluntary and skeletal muscle is involuntary.', 2, 'A is true. R is false: it is the other way round. Skeletal is voluntary; cardiac is involuntary.');

stm(3, 'epithelial', 'Epithelial tissue has a free surface facing a body fluid or the outside.', 'Epithelial cells are separated by large amounts of matrix.', 2, 'I is true. II is false: epithelial cells are compactly packed with little matrix.');
stm(3, 'connective', 'Dense regular tissue has fibres in parallel bundles.', 'Dense irregular tissue has fibres oriented in different directions.', 0, 'Both are correct descriptions. Tendons and ligaments are regular; skin dermis is irregular.');
stm(3, 'glands', 'Exocrine glands release their secretions through ducts.', 'Endocrine glands release their secretions through ducts to the outside.', 2, 'II is false: endocrine glands have no ducts.');
stm(4, 'muscular', 'Skeletal muscle fibres are striated and voluntary.', 'Cardiac muscle fibres are striated and voluntary.', 2, 'Cardiac muscle is striated but involuntary.');
stm(4, 'neural', 'Neurons are excitable cells.', 'Neuroglia make up less than one-half the volume of neural tissue.', 2, 'I is true. II is false; neuroglia form more than half.');
stm(4, 'epithelial', 'Tight junctions help stop leakage across a tissue.', 'Adhering junctions cement neighbouring cells together.', 0, 'Both match the NCERT functions of the junctions.');
stm(4, 'connective', 'Blood, bone and cartilage are specialised connective tissues.', 'Tendons and ligaments are specialised connective tissues.', 2, 'NCERT places tendons and ligaments under dense regular connective tissue, not under specialised connective tissue.');
mc(4, 'connective', 'Consider: (i) Areolar tissue is loose connective tissue. (ii) Adipose tissue stores fat. (iii) Ligament joins muscle to bone. (iv) Cartilage cells lie in lacunae. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(i), (ii) and (iv) are correct. (iii) is wrong because a ligament joins bone to bone; a tendon joins muscle to bone.', 'Tendon and ligament are swapped in (iii).', 'statements');
mc(4, 'epithelial', 'Consider: (i) Goblet cells are unicellular glands. (ii) Simple squamous epithelium lines alveoli. (iii) Cuboidal epithelium lines the ducts of glands. (iv) Ciliated epithelium lines the stomach. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(i), (ii) and (iii) are correct. The stomach is lined by simple columnar epithelium, not ciliated epithelium (which lines bronchioles and fallopian tubes).', null, 'statements');
mc(5, 'muscular', 'Consider: (i) Skeletal muscle is striated. (ii) Smooth muscle is striated. (iii) Cardiac muscle is branched. (iv) Skeletal muscle is attached to bones. (v) Smooth muscle is voluntary. How many are correct?', 'Three', ['Two', 'Four', 'Five'], '(i), (iii) and (iv) are correct. (ii) and (v) are wrong: smooth muscle is unstriated and involuntary.', 'Do not count (ii) or (v).', 'statements');
mc(5, 'mixed', 'Consider these cells: neuron, osteocyte, chondrocyte, goblet cell, macrophage. In how many of them is the cell NOT found within a lacuna of its tissue?', 'Three', ['Two', 'Four', 'One'], 'Only osteocyte (bone) and chondrocyte (cartilage) lie in lacunae. The other three are not in lacunae.', 'Read the question: it asks for NOT in lacunae.', 'statements');

// ---- Matches
match(2, 'connective', 'atx1', 'Cell and feature', ['A. Fibroblast', 'B. Chondrocyte', 'C. Osteocyte', 'D. Goblet cell'], ['p. Secretes mucus', 'q. Lies in a bone lacuna', 'r. Lies in a cartilage lacuna', 's. Makes fibres of the matrix'], 'A-s, B-r, C-q, D-p', ['A-r, B-s, C-q, D-p', 'A-s, B-q, C-r, D-p', 'A-s, B-r, C-p, D-q'], 'Fibroblasts make fibres; chondrocytes sit in cartilage lacunae; osteocytes in bone lacunae; goblet cells secrete mucus.');
match(3, 'connective', 'atx2', 'Tissue and property', ['A. Adipose tissue', 'B. Dense regular tissue', 'C. Cartilage', 'D. Blood'], ['p. Joins muscle to bone', 'q. Stores fat under the skin', 'r. Fluid matrix', 's. Solid pliable matrix that resists compression'], 'A-q, B-p, C-s, D-r', ['A-p, B-q, C-s, D-r', 'A-q, B-p, C-r, D-s', 'A-s, B-p, C-q, D-r'], 'Adipose: fat storage; dense regular (tendon): muscle to bone; cartilage: solid pliable matrix; blood: fluid matrix.');
match(3, 'epithelial', 'atx3', 'Epithelium and feature', ['A. Simple squamous', 'B. Simple columnar', 'C. Compound', 'D. Goblet cell'], ['p. Several layers, protective', 'q. Thin flat cells, diffusion', 'r. Tall cells with nuclei at the base', 's. Unicellular gland'], 'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-p, C-r, D-s', 'A-q, B-r, C-s, D-p'], 'Squamous: thin and flat. Columnar: tall, nuclei basal. Compound: layered protection. Goblet: single-celled gland.');
match(3, 'muscular', 'atx4', 'Tissue and place', ['A. Skeletal muscle', 'B. Cardiac muscle', 'C. Smooth muscle', 'D. Neural tissue'], ['p. Biceps', 'q. Wall of the stomach', 'r. Heart', 's. Brain and spinal cord'], 'A-p, B-r, C-q, D-s', ['A-r, B-p, C-q, D-s', 'A-p, B-q, C-r, D-s', 'A-p, B-r, C-s, D-q'], 'Biceps is skeletal, heart wall is cardiac, stomach wall is smooth, and the brain and cord are neural tissue.');
match(4, 'glands', 'atx5', 'Gland and type', ['A. Salivary gland', 'B. Thyroid gland', 'C. Goblet cell', 'D. Pancreas'], ['p. Unicellular exocrine', 'q. Multicellular exocrine', 'r. Endocrine', 's. Both exocrine and endocrine'], 'A-q, B-r, C-p, D-s', ['A-q, B-r, C-s, D-p', 'A-r, B-q, C-p, D-s', 'A-p, B-r, C-q, D-s'], 'Salivary: multicellular exocrine. Thyroid: endocrine. Goblet: unicellular exocrine. Pancreas: both.');
match(4, 'epithelial', 'atx6', 'Epithelium and place', ['A. Compound', 'B. Simple cuboidal', 'C. Ciliated', 'D. Simple squamous'], ['p. Fallopian tube', 'q. Lining of blood vessels', 'r. Buccal cavity', 's. Tubular part of nephron', 't. Stomach lining'], 'A-r, B-s, C-p, D-q', ['A-s, B-r, C-p, D-q', 'A-r, B-s, C-q, D-p', 'A-r, B-t, C-p, D-q'], 'Compound: buccal cavity. Cuboidal: nephron tubule. Ciliated: fallopian tube. Squamous: blood vessel lining. The stomach lining (t) is columnar and matches none here.');
match(4, 'connective', 'atx7', 'Tissue and matrix', ['A. Bone', 'B. Cartilage', 'C. Blood', 'D. Areolar tissue'], ['p. Fluid matrix', 'q. Hard matrix with calcium salts', 'r. Solid pliable matrix', 's. Loose network of fibres'], 'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-r, C-s, D-p', 'A-p, B-r, C-q, D-s'], 'Each tissue is told by its matrix.');
match(4, 'mixed', 'atx8', 'Structure and place', ['A. Brush border', 'B. Cilia', 'C. Intercalated disc', 'D. Lacuna'], ['p. Cardiac muscle', 'q. Intestinal epithelium', 'r. Bone or cartilage', 's. Bronchiole epithelium'], 'A-q, B-s, C-p, D-r', ['A-s, B-q, C-p, D-r', 'A-q, B-s, C-r, D-p', 'A-q, B-p, C-s, D-r'], 'Microvilli form a brush border in the intestine; cilia are in bronchioles; intercalated discs are in the heart; lacunae hold bone and cartilage cells.');
match(5, 'mixed', 'atx9', 'Organ part and tissue', ['A. Inner lining of the intestine', 'B. Tendon', 'C. Lining of a blood vessel', 'D. Fat pad under the skin'], ['p. Adipose tissue', 'q. Simple squamous epithelium', 'r. Dense regular connective tissue', 's. Simple columnar epithelium'], 'A-s, B-r, C-q, D-p', ['A-q, B-r, C-s, D-p', 'A-s, B-p, C-q, D-r', 'A-r, B-s, C-q, D-p'], 'Intestine: columnar. Tendon: dense regular. Vessel lining: squamous. Fat pad: adipose.');
match(5, 'basics', 'atx10', 'Item and number named in NCERT', ['A. Types of cell junction in epithelium', 'B. Types of dense connective tissue', 'C. Basic animal tissue types', 'D. Cell types named in areolar tissue'], ['p. 2', 'q. 3', 'r. 4', 's. 5'], 'A-q, B-p, C-r, D-q', ['A-q, B-p, C-r, D-p', 'A-r, B-p, C-q, D-q', 'A-q, B-q, C-r, D-p'], 'Junctions: tight, adhering, gap = 3. Dense: regular and irregular = 2. Tissues = 4. Areolar cells: fibroblasts, macrophages, mast cells = 3. One entry in List II may match two items.', 'Two List I items share the same answer.');

// ---- Passages
pass('atx11', 'Passage: three slides', 'A student looks at three slides. Slide X shows a single layer of very thin, flat cells. Slide Y shows cells lying singly in small cavities inside a solid, pliable, translucent matrix. Slide Z shows long, unbranched, cylindrical fibres with light and dark bands, held together by sheaths of connective tissue.');
pq('atx11', 3, 'mixed', 'Slide X is most likely taken from', 'the wall of an air sac of the lung', ['the lining of the stomach', 'the skin surface', 'a tendon'], 'A single layer of thin flat cells is simple squamous epithelium, found in lung air sacs.');
pq('atx11', 4, 'mixed', 'The cells in slide Y are called', 'chondrocytes', ['osteocytes', 'fibroblasts', 'neuroglia'], 'A solid pliable matrix with cells in cavities is cartilage; its cells are chondrocytes. Bone matrix would be hard and rich in calcium salts.');
pq('atx11', 5, 'muscular', 'Slide Z shows a tissue that is', 'skeletal muscle, voluntary and attached to bones', ['cardiac muscle, involuntary and branched', 'smooth muscle, unstriated and fusiform', 'dense regular connective tissue'], 'Cylindrical, unbranched, banded fibres are skeletal muscle.');
pass('atx12', 'Passage: gland experiment', 'Gland P has a duct that opens into the mouth. Gland Q has no duct and its product enters the fluid around it. Cell R is a single cell in the intestinal lining that secretes a slippery substance onto the surface.');
pq('atx12', 3, 'glands', 'Gland Q is', 'an endocrine gland releasing hormones', ['an exocrine gland releasing saliva', 'a unicellular gland', 'a goblet cell'], 'No duct means endocrine. Hormones are its products.');
pq('atx12', 4, 'glands', 'Which of the following describes cell R?', 'A unicellular exocrine gland', ['A multicellular exocrine gland', 'An endocrine gland', 'A neuron'], 'A single secretory cell making mucus is a goblet cell.');
pq('atx12', 4, 'glands', 'Gland P could be', 'a salivary gland', ['the thyroid gland', 'the adrenal gland', 'the pituitary gland'], 'It has a duct leading into the mouth, so it is exocrine: the salivary gland.');
pass('atx13', 'Passage: heart and gut', 'A section from the wall of the heart shows striated fibres that branch and meet at dark lines. A section from the wall of the small intestine shows an inner layer of tall cells with finger-like surface projections and a deeper layer of spindle-shaped cells with a single central nucleus and no striations.');
pq('atx13', 3, 'muscular', 'The dark lines where heart fibres meet are', 'intercalated discs', ['lacunae', 'microvilli', 'tendons'], 'Intercalated discs hold cardiac fibres together and let signals pass.');
pq('atx13', 4, 'muscular', 'The deeper layer in the intestine wall is', 'smooth muscle, involuntary', ['skeletal muscle, voluntary', 'cardiac muscle, involuntary', 'neural tissue'], 'Spindle-shaped, single nucleus and no striations: smooth muscle.');
pq('atx13', 5, 'epithelial', 'Which pair is correct for the intestine section and the heart section?', 'Inner layer: simple columnar epithelium; heart fibres: striated and involuntary', ['Inner layer: simple squamous; heart fibres: striated and voluntary', 'Inner layer: compound; heart fibres: smooth', 'Inner layer: cuboidal; heart fibres: unstriated'], 'Tall cells with projections: simple columnar with microvilli. Heart: striated, involuntary.');

// ---- Level 4
mc(4, 'epithelial', 'Which of the following is NOT a feature of epithelial tissue?', 'Rich in cells scattered in a large matrix', ['Cells closely packed', 'A free surface', 'Several junction types'], 'Wide spacing in a big matrix is a connective tissue feature.');
mc(4, 'epithelial', 'An epithelium of several layers cannot be good for', 'rapid diffusion of gases', ['protection against abrasion', 'lining the buccal cavity', 'covering the skin'], 'More layers means a longer path, so thin simple squamous epithelium is used for diffusion.');
mc(4, 'epithelial', 'A tissue has a single layer of cube-shaped cells with microvilli. It would most probably absorb', 'substances from a tubule', ['impulses', 'oxygen from air', 'sound waves'], 'Cuboidal cells with microvilli suit absorption, as in kidney tubules.');
mc(4, 'connective', 'Which of these has the most abundant intercellular matrix relative to cells?', 'Bone', ['Simple squamous epithelium', 'Cardiac muscle', 'Neural tissue'], 'Bone and other connective tissues have much matrix. The other three are mostly cells.');
mc(4, 'connective', 'Which statement about cartilage is incorrect?', 'Its matrix is hard because it is full of calcium salts', ['Its cells lie in cavities', 'It resists compression', 'It is found in the tip of the nose'], 'The matrix is solid and pliable. Calcium salts harden bone, not cartilage.');
mc(4, 'connective', 'The strongest, least stretchable of these connective tissues for pulling force is', 'dense regular connective tissue', ['areolar tissue', 'adipose tissue', 'blood'], 'Parallel packed collagen fibres give great tensile strength to tendons and ligaments.');
mc(4, 'muscular', 'Which of these feature pairs is true for skeletal muscle?', 'Striated and attached to bones', ['Branched and involuntary', 'Fusiform and unstriated', 'Wall of stomach and voluntary'], 'Skeletal muscle fibres are cylindrical, unbranched and striated.');
mc(4, 'muscular', 'Which statement about cardiac muscle cells is correct?', 'Their plasma membranes are fused at some points', ['They are bundled in sheaths around bones', 'They have no striations', 'They are voluntary'], 'Fusion points are intercalated discs.');
mc(4, 'neural', 'Which of these cells can both receive and send signals?', 'Neuron', ['Neuroglia', 'Osteocyte', 'Goblet cell'], 'Neurons are excitable. Neuroglia only support them.');
mc(4, 'mixed', 'A student claims that a hormone is released from the pancreas into a duct leading to the intestine. This is', 'wrong: the enzyme part is released through a duct, hormones go into the blood', ['correct: all pancreatic products use the duct', 'wrong: the pancreas is not a gland', 'correct: the pancreas has only an exocrine part'], 'The pancreas has an exocrine part (enzymes via duct) and an endocrine part (hormones into blood).', 'The pancreas is both.');
mc(4, 'mixed', 'Which tissue type is described as: cells in a matrix, fluid, circulates through the body?', 'Blood', ['Areolar tissue', 'Cartilage', 'Adipose tissue'], 'Blood is the main circulating fluid that helps in transport.');
mc(4, 'mixed', 'Which of the following is a correct pairing of tissue and the substance it forms or stores?', 'Adipose tissue and fat', ['Cartilage and haemoglobin', 'Blood and keratin only', 'Neural tissue and collagen only'], 'Adipose stores fat.');
mc(4, 'epithelial', 'Which cell junction would you expect to be most abundant in a tissue where nothing must leak between cells, such as the lining of a tube that must contain fluid?', 'Tight junctions', ['Gap junctions', 'Intercalated discs', 'Lacunae'], 'Tight junctions seal the space between cells.');
mc(4, 'epithelial', 'Which junction helps coordinate beating or contraction by letting ions pass directly between cells?', 'Gap junction', ['Tight junction', 'Adhering junction', 'Microvillus'], 'Direct cytoplasmic channels carry ions and small molecules.');
mc(4, 'connective', 'Which of the following combinations is correct?', 'Tendon: muscle to bone; ligament: bone to bone', ['Tendon: bone to bone; ligament: muscle to bone', 'Tendon: muscle to muscle; ligament: skin to bone', 'Tendon: cartilage to bone; ligament: bone to nerve'], 'A tendon passes the pull of a muscle to a bone; a ligament holds two bones together at a joint.', 'The two names are often swapped.');
mc(4, 'connective', 'Which cell type is NOT a part of areolar tissue?', 'Osteocyte', ['Fibroblast', 'Macrophage', 'Mast cell'], 'Osteocytes live in bone.');

// ---- Level 5
mc(5, 'epithelial', 'Which of these tissues does NOT have a role in secretion?', 'Simple squamous epithelium of the alveolus', ['Simple columnar epithelium of the stomach', 'Cuboidal epithelium of a gland duct', 'Goblet cell'], 'Squamous epithelium is thin for diffusion and filtration; secretion is by columnar, cuboidal and glandular cells.');
mc(5, 'mixed', 'A tissue lacking blood vessels yet nourished by diffusion, with cells in lacunae in a pliable matrix, is', 'cartilage', ['bone', 'areolar tissue', 'blood'], 'Cartilage is avascular, with chondrocytes in lacunae; its matrix is solid and pliable.', 'Bone is also in lacunae but has a hard, vascular matrix.');
mc(5, 'muscular', 'Which of the following is true for both smooth and cardiac muscle but NOT for skeletal muscle?', 'Involuntary control', ['Striations', 'Attachment to bones', 'Cylindrical multinucleate fibres'], 'Smooth and cardiac muscles are involuntary. Only cardiac is striated.');
mc(5, 'connective', 'Which of these is a correct list of ALL components of blood?', 'Plasma, RBCs, WBCs and platelets', ['Plasma and RBCs only', 'RBCs, WBCs and neurons', 'Plasma, bone marrow and RBCs'], 'Blood = fluid plasma + RBCs + WBCs + platelets.');
mc(5, 'mixed', 'Which one is NOT a tissue-level difference between bone and blood?', 'Both have cells in a matrix', ['Bone matrix is hard, blood matrix fluid', 'Bone is rich in calcium salts', 'Blood circulates'], 'Both are connective tissues with cells in a matrix; that is the similarity, not a difference.', 'Read the NOT.');
mc(5, 'neural', 'Which pair is correct for neural tissue?', 'Neurons: excitable; neuroglia: more than half the volume', ['Neurons: support cells; neuroglia: excitable', 'Neurons: less than half the cells; neuroglia: conduct impulses', 'Neurons: store fat; neuroglia: contract'], 'NCERT statements.');
mc(5, 'glands', 'Which of the following does NOT release its product by a duct?', 'Thyroid gland', ['Salivary gland', 'A goblet cell onto the surface', 'The exocrine pancreas'], 'The thyroid is an endocrine gland. A goblet cell releases mucus directly onto the surface.');
mc(5, 'mixed', 'Which of these is the correct sequence from the free surface inwards in the wall of the intestine (simplified)?', 'Epithelium, then connective tissue, then smooth muscle', ['Bone, then epithelium, then neural tissue', 'Smooth muscle, then bone, then epithelium', 'Cartilage, then cardiac muscle, then epithelium'], 'A simplified gut wall has an inner lining epithelium, connective tissue and muscle.');
stm(5, 'connective', 'Cartilage and bone both have cells lying in cavities of their matrix.', 'The matrix of cartilage is rich in calcium salts like that of bone.', 2, 'I is true: chondrocytes and osteocytes both lie in lacunae. II is false: calcium salts harden the bone matrix, while cartilage matrix is solid and pliable.');
export default { topic: 'animal-tissues', groups, items, gens: [] };
